// Splash images (iOS Splash.imageset + Android drawable*/splash.png, each file keeps its size): the new logo
// icon + "FILM CAMELA" wordmark on the app's near-black. Generated by scripts/gen-brand-icons.py.
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const script = fileURLToPath(new URL('./gen-brand-icons.py', import.meta.url));
for (const py of process.platform === 'win32' ? ['python', 'py'] : ['python3', 'python']) {
  const r = spawnSync(py, [script, 'splash'], { stdio: 'inherit' });
  if (!r.error) process.exit(r.status ?? 1);
}
console.error('gen-splash: Python 3 with Pillow + numpy is required (pip install pillow numpy).');
process.exit(1);
